<script setup>
import {ref,onMounted,provide} from 'vue';import {Home,PlaySquare,Bookmark,Search,Menu,WifiOff,MapPin,Bell,Newspaper,Flame,MessageCircleMore,MapPinned,X,UserRound,Settings,Building2,Map,Globe2,Trophy,Heart,Clapperboard,ChevronRight} from 'lucide-vue-next';
const online=ref(navigator.onLine),tab=ref('top'),drawer=ref(false),category=ref('');provide('homeTab',tab);provide('menuCategory',category);
function choose(c){category.value=c;tab.value='top';drawer.value=false}
