const menu=[['શહેર','city',Building2],['ગુજરાત','state',Map],['વિશ્વ','world',Globe2],['સ્પોર્ટ્સ','sports',Trophy],['લાઇફસ્ટાઇલ','lifestyle',Heart],['સિનેમા','cinema',Clapperboard]];
</script>
<template><div class="ref-app"><div v-if="!online" class="ref-offline"><WifiOff/> ઓફલાઇન મોડ · ડાઉનલોડ થયેલા સમાચાર</div><header class="ref-header"><button @click="drawer=true"><Menu/></button><router-link to="/" class="ref-brand"><i>P</i><span><b>PULSE</b><small>ગુજરાત</small></span></router-link><div><button><Search/></button><button><Bell/></button></div></header><div class="ref-location"><MapPin/> રાજકોટ <span>શહેર બદલો</span></div><nav class="editor-tabs"><button :class="{on:tab==='top'}" @click="tab='top';category=''"><Flame/> ટોપ ન્યૂઝ</button><button :class="{on:tab==='gossip'}" @click="tab='gossip'"><MessageCircleMore/> ગપશપ</button><button :class="{on:tab==='local'}" @click="tab='local'"><MapPinned/> મારું શહેર</button></nav><main><router-view/></main><nav class="ref-bottom"><router-link to="/"><Home/><span>હોમ</span></router-link><router-link to="/shorts"><PlaySquare/><span>વિડિયો</span></router-link><a class="paper"><Newspaper/><span>ઈ-પેપર</span></a><a><Bookmark/><span>સેવ</span></a><router-link to="/polls"><Search/><span>શોધ</span></router-link></nav><transition name="drawer"><div v-if="drawer" class="drawer-backdrop" @click.self="drawer=false"><aside class="side-drawer"><button class="drawer-close" @click="drawer=false"><X/></button><div class="drawer-profile"><div class="avatar"><UserRound/></div><div><b>નમસ્તે, વાચક</b><span>લૉગિન / પ્રોફાઇલ જુઓ</span></div><ChevronRight/></div><div class="drawer-place"><MapPin/><div><small>તમારું શહેર</small><b>રાજકોટ, ગુજરાત</b></div><button>બદલો</button></div><nav><button v-for="m in menu" @click="choose(m[1])"><component :is="m[2]"/><span>{{m[0]}}</span><ChevronRight/></button></nav><div class="drawer-bottom"><button><UserRound/> પ્રોફાઇલ</button><button><Settings/> સેટિંગ્સ</button></div></aside></div></transition></div></template>